export function validateSpaces(raw){if(!Array.isArray(raw)||raw.length>100)throw Error('Парковочные места: массив до 100 прямоугольников');for(const r of raw){if(!Array.isArray(r)||r.length!==4||r.some(x=>!Number.isFinite(x))||r[0]<0||r[1]<0||r[2]<=0||r[3]<=0||r[0]+r[2]>1||r[1]+r[3]>1)throw Error('Место задаётся [x,y,width,height] в диапазоне 0..1');}return raw;}
export class Observations{
 constructor(spaces=[]){this.spaces=validateSpaces(spaces);this.still=new Map();this.events=[];this.occupancy=[];}
 update(tracks,time){this.occupancy=this.spaces.map((r,i)=>({space:i+1,occupied:tracks.some(t=>t.x>=r[0]&&t.x<=r[0]+r[2]&&t.y>=r[1]&&t.y<=r[1]+r[3]),time}));const ids=new Set(tracks.map(t=>t.id));for(const [id,m]of this.still)if(!ids.has(id)&&time-m.last>1)this.still.delete(id);for(const t of tracks){let m=this.still.get(t.id);if(!m||Math.hypot(t.x-m.x,t.y-m.y)>.012){m={x:t.x,y:t.y,since:time,last:time,emitted:false};this.still.set(t.id,m);}m.last=time;if(time-m.since>=10&&!m.emitted){m.emitted=true;this.events.push({type:'possible_stopped_vehicle',trackId:t.id,start:m.since,end:time,class:t.class,requiresReview:true,reason:'Центр трека сместился менее чем на 1.2% кадра за 10 с. Возможна обычная остановка на красный.'});}}return this.occupancy;}
}
